onClick:
{{(() => {
  const startText = String(StartMinutes.text ?? "").trim();
  const durationText = String(DurationMinutes.text ?? "").trim();
  const blocked = RoomBlocked.isSwitchedOn;
  const start = Number(startText);
  const duration = Number(durationText);
  const end = start + duration;

  function respond(available, reasonCode, message) {
    return storeValue("roomCheck", { startText, durationText, blocked, available, reasonCode, message }, false);
  }

  if (!startText || !Number.isInteger(start) || start < 0 || start >= 1440) {
    return respond(false, "INVALID_START", "Enter a whole start minute from 0 to 1439.");
  }
  if (!durationText || !Number.isInteger(duration) || duration < 1 || duration > 120) {
    return respond(false, "DURATION", "Enter a duration of 1 to 120 whole minutes.");
  }
  if (start <= 540) {
    return respond(false, "PAST_TIME", "Start time must be after 09:00.");
  }
  if (end > 1440) {
    return respond(false, "INVALID_INTERVAL", "The interval must end by midnight.");
  }
  if (blocked) {
    return respond(false, "BLOCKED", "Unavailable — Room A101 is blocked.");
  }
  if (start < 660 && end > 600) {
    return respond(false, "OVERLAP", "Unavailable — this overlaps the 10:00–11:00 booking.");
  }
  const clock = minutes => [Math.floor(minutes / 60), minutes % 60]
    .map(part => String(part).padStart(2, "0")).join(":");
  return respond(true, "AVAILABLE", "Available — Room A101 is free from " + clock(start) + " to " + clock(end) + ".");
})()}}
